use std::error::Error;

use l2_canary::{AgentId, RunId};
use l2_codecs::{LldpFrame, Tlv, Validity, encode_lldp, lldp_encoded_len};
use l2_core::{EthernetFrame, FrameField, encode, encoded_len};
use l2_lab::discovery::{DiscoveryLab, Expectation, Identity, Probe, Protocol};
use l2_onpath::Budget;

pub const LLDP_DEVICE: &[u8] = b"\x07switch-a";
pub const LLDP_PORT: &[u8] = b"\x05Gi1/0/1";
pub const CDP_DEVICE: &[u8] = b"switch-a";
pub const CDP_PORT: &[u8] = b"Gi1/0/1";

// Generated by Scapy 2.8.0 with CDPv2 device and port TLVs and an odd payload
pub const CDP_GOLDEN: &[u8] = &[
    0x01, 0x00, 0x0c, 0xcc, 0xcc, 0xcc, 0x02, 0, 0, 0, 0, 1, 0, 0x23, 0xaa, 0xaa, 0x03, 0, 0, 0x0c,
    0x20, 0, 2, 0x78, 0xe6, 0xbe, 0, 1, 0, 0x0c, b's', b'w', b'i', b't', b'c', b'h', b'-', b'a', 0,
    3, 0, 0x0b, b'G', b'i', b'1', b'/', b'0', b'/', b'1',
];

pub fn lldp(ttl: u16) -> Result<Vec<u8>, Box<dyn Error>> {
    let ttl_bytes = ttl.to_be_bytes();
    let frame = LldpFrame {
        tlvs: vec![
            Tlv {
                kind: 1,
                value: LLDP_DEVICE,
                offset: 0,
            },
            Tlv {
                kind: 2,
                value: LLDP_PORT,
                offset: 0,
            },
            Tlv {
                kind: 3,
                value: &ttl_bytes,
                offset: 0,
            },
        ],
        padding: &[],
        validity: Validity::Valid,
    };
    let mut payload = vec![0; lldp_encoded_len(&frame)?];
    encode_lldp(&frame, &mut payload)?;
    let ethernet = EthernetFrame {
        destination: [1, 0x80, 0xc2, 0, 0, 0x0e],
        source: [2, 0, 0, 0, 0, 1],
        vlan_tags: Vec::new(),
        payload: &payload,
        padding: &[],
        field: FrameField::EtherType(0x88cc),
    };
    let mut wire = vec![0; encoded_len(&ethernet)?];
    encode(&ethernet, &mut wire)?;
    Ok(wire)
}

pub fn source() -> Result<AgentId, Box<dyn Error>> {
    Ok(AgentId::new([1; 16])?)
}
pub fn receiver() -> Result<AgentId, Box<dyn Error>> {
    Ok(AgentId::new([2; 16])?)
}
pub fn run_id() -> Result<RunId, Box<dyn Error>> {
    Ok(RunId::from_recorded([3; 16])?)
}
pub fn budget() -> Result<Budget, Box<dyn Error>> {
    Ok(Budget::new(64, 100_000, 300_000)?)
}

pub fn lab<'a>(probes: &'a [Probe<'a>]) -> Result<DiscoveryLab<'a>, Box<dyn Error>> {
    Ok(DiscoveryLab::new(run_id()?, receiver()?, probes)?)
}

pub fn probe<'a>(
    sequence: u64,
    at: u64,
    protocol: Protocol,
    frame: &'a [u8],
    expectation: Expectation<'a>,
) -> Result<Probe<'a>, Box<dyn Error>> {
    Ok(Probe::new(
        sequence,
        at,
        source()?,
        protocol,
        frame,
        expectation,
    ))
}

pub const fn lldp_identity() -> Identity<'static> {
    Identity::new(LLDP_DEVICE, LLDP_PORT)
}
pub const fn cdp_identity() -> Identity<'static> {
    Identity::new(CDP_DEVICE, CDP_PORT)
}
